        if (docs > 0) { cap = Math.min(cap, Math.max(C.CAP_FLOOR, C.CAP_BASE - C.CAPK_W * docs)); }
        if (pers > 0 || rights > 0) { cap = Math.min(cap, Math.max(C.CAP_FLOOR, C.CAP_BASE - C.CAPD_W * pers - C.CAPR_W * rights)); }
        return cap;
    }

    // Weeks 1..T rebuilt from the decisions; the receivables balance is derived here, never stored.
    function weeksOf(dec, T) {
        var d1 = dec.round1;
        var out = [];
        var ar = C.AR0;
        var w;
        for (w = 1; w <= T; w++) {
            var d2 = w >= 2 ? dec.round2 : PRE2;
            var d3 = w >= 3 ? dec.round3 : PRE3;
            var d4 = w >= 4 ? dec.round4 : null;
            var a = C.ADOPT[d3.chg];
            var exc = C.EXC_P * (1.0 - a) + C.EXC_D * a;
            var hInv;
            if (d1.inv === 'match') { hInv = C.N_INV * (C.MATCH_MIN + C.EXC_MIN * exc) / 60.0; }
            else { hInv = C.N_INV * C.INV_MIN[d1.inv] / 60.0; }
            var err = C.N_INV * C.INV_ERR[d1.inv];
            var errm = 1.0;
            if (d1.inv === 'auto' && (d2.appr === 'rules' || d3.pay === 'autodebit')) { errm = C.AUTO_RULES; }
            var miss = C.MISS[d1.mail];
            var lateSh = 1.0 - (1.0 - miss) * (1.0 - C.APP_LATE[d2.appr]);
            var discSh = C.APP_DISC[d2.appr];
            if (d3.pay === 'autodebit') { lateSh = miss; discSh = C.AD_DISC; }
            var late = C.N_INV * lateSh;
            var disc = C.N_INV * C.DISC_SH * discSh * C.INV_AVG * C.DISC;
            var nmiss = C.N_NOT * C.NOT_MISS[d1.nt];
            var signed = C.N_BUD * C.SIGN_ACC[d2.sign];
            var disputes = d2.sign === 'reply' ? signed * C.DISPUTE : 0.0;
            var lostp = C.LOST_P * (1.0 - a) + C.LOST_D * a + (d3.chg === 'force' ? C.FORCE_LOST : 0.0);
            var lostAlb = C.N_ALB * lostp;
            var coll = ar * C.COLL[d3.first];
            var lostcl = d3.first === 'bulk' ? C.LOSTCL : 0.0;
            var hours = C.BASE_H + hInv + C.MAIL_H[d1.mail] + C.NOT_H[d1.nt] + C.APP_H[d2.appr] + C.SIGN_H[d2.sign];
            hours += C.ARCH_H[d2.arch] + C.PAY_H[d3.pay] + C.CALL_H[d3.first];
            if (d2.arch === 'shred') { hours += C.SCAN_H; }
            if (w === 1) { hours += C.INV_SET[d1.inv] + C.MAIL_SET[d1.mail] + C.NOT_SET[d1.nt]; }
            if (w === 2) { hours += C.APP_SET[d2.appr] + C.SIGN_SET[d2.sign] + C.ARCH_SET[d2.arch]; }
            if (w === 3) { hours += C.AUTO_SET[d3.first] + C.PAY_SET[d3.pay] + C.CHG_H[d3.chg]; }
            var ownerH = C.NOT_OWN[d1.nt] + C.APP_OWN[d2.appr];
            var fees = C.INV_LIC[d1.inv] + C.NOT_FEE[d1.nt] + C.ARCH_LIC[d2.arch] + C.SIGN_FIX[d2.sign];
            fees += C.SIGN_VAR[d2.sign] * C.N_BUD;
            if (d1.mail === 'print') { fees += C.PRINT_C; }
            if (w === 3 && d3.chg === 'train') { fees += C.TRAIN_C; }
            var rights = 0.0;
            var pers = 0.0;
            var docs = 0.0;
            if (d2.arch === 'shred') { docs += C.N_INV * C.PAPER + C.N_ALB * (1.0 - a) + (w === 2 ? C.SHRED_STOCK : 0.0); }
            if (d4 !== null) {
                if (d4.req === 'proper') { hours += C.REQ_H[d2.arch]; }
                else if (d4.req === 'lawyer') { fees += C.LAWYER; }
                else { rights += 2.0; }
                hours += C.CV_H[d4.cv];
                if (d4.cv === 'share') { pers += C.CVS; }
                hours += C.BOX_H[d4.box];
                if (d4.box === 'store') { fees += C.BOX_KEEP; }
                else if (d4.box === 'schedule') { fees += C.BOX_CERT; }
                else { docs += C.BOX_DOCS; }
            }
            var ot = Math.max(0.0, hours - C.CAP_H);
            var costH = hours * C.WAGE + ot * C.OT + ownerH * C.OWNER;
            var costErr = err * errm * C.ERR_C + C.N_INV * C.PAY_ERR[d3.pay] * C.ERR_C;
            if (d3.pay === 'autodebit') { costErr += C.N_INV * C.DUP * C.DUP_C; }
            var costLate = late * C.LATE_C;
            var costNot = nmiss * C.PEN;
            var costLost = lostAlb * C.ALB_V + disputes * C.DISPUTE_C + lostcl * C.LOSTCL_C;
            var value = signed * C.JOB_M + disc + coll * C.COLL_V;
            var cost = costH + fees + costErr + costLate + costNot + costLost;
            var res = value - cost;
            var badPay = C.N_INV * C.PAY_ERR[d3.pay] + (d3.pay === 'autodebit' ? C.N_INV * C.DUP : 0.0);
            var okInv = C.N_INV * (1.0 - lateSh) - err * errm - badPay;
            var okN = C.N_NOT - nmiss;
            var okp = 100.0 * (okInv + okN) / (C.N_INV + C.N_NOT);
            out.push({ w: w, hours: hours, ot: ot, owner_h: ownerH, h_inv: hInv, err: err * errm, late: late, disc: disc, nmiss: nmiss,
                signed: signed, disputes: disputes, lost_alb: lostAlb, coll: coll, ar: ar, lostcl: lostcl, fees: fees,
                cost_h: costH, cost_err: costErr, cost_late: costLate, cost_not: costNot, cost_lost: costLost,
                value: value, cost: cost, res: res, okp: okp, docs: docs, pers: pers, rights: rights, adopt: 100.0 * a });
            ar = ar - coll + C.AR_NEW;
        }
        return out;
    }

    function periodResult(dec, r) {
        var q = weeksOf(dec, r)[r - 1];
        q.t = r;
        return q;
    }

    class LaOficinaDigital2140Adapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'La Oficina Digital';
            this.version = '1.0.0';
            this.ROUNDS = [
                { panel: 'roundPanel1', nameKey: 'r1_name', briefKey: 'r1_brief' },
                { panel: 'roundPanel2', nameKey: 'r2_name', briefKey: 'r2_brief' },
                { panel: 'roundPanel3', nameKey: 'r3_name', briefKey: 'r3_brief' },
                { panel: 'roundPanel4', nameKey: 'r4_name', briefKey: 'r4_brief' }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    rounds: [],
                    periods: [],
                    docsCum: 0,
                    persCum: 0,
                    rightsCum: 0,
                    dec: {},
                    scoreHistory: [],
                    performance: { overallScore: 0 },
                    performanceTier: 'beginner'
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            this._syncControlsFromDecisions(state);
            this._updateBriefing(state);
        }

        _syncControlsFromDecisions(state) {
            var raw = (state && state.decisions) || {};
            var saved = (state && state.domainState && state.domainState.dec) || {};
            var d = {
                round1: raw.round1 || saved.round1,
                round2: raw.round2 || saved.round2,
                round3: raw.round3 || saved.round3,
                round4: raw.round4 || saved.round4
            };
            var set = function(id, val) {
                var el = document.getElementById(id);
                if (el && val !== undefined && val !== null) { el.value = String(val); }
            };
            if (d.round1) { set('r1_inv', d.round1.inv); set('r1_mail', d.round1.mail); set('r1_nt', d.round1.nt); }
            if (d.round2) { set('r2_appr', d.round2.appr); set('r2_sign', d.round2.sign); set('r2_arch', d.round2.arch); }
            if (d.round3) { set('r3_first', d.round3.first); set('r3_pay', d.round3.pay); set('r3_chg', d.round3.chg); }
            if (d.round4) { set('r4_req', d.round4.req); set('r4_cv', d.round4.cv); set('r4_box', d.round4.box); }
        }

        _t(key, vars) {
            return window.mySimulation ? window.mySimulation.t(key, vars) : key;
        }

        _cl(key, fallback) {
            var s = this._t(key);
            return s === key ? fallback : s;
        }

        _lang() {
            return (window.mySimulation && window.mySimulation.language === 'en') ? 'en' : 'es';
        }

        // Spanish format in es (point thousands, comma decimals); English format in en.
        _fmtNum(v, dec) {
            var n = Number(v) || 0;
            var neg = n < 0;
            var f = Math.abs(n).toFixed(dec);
            var parts = f.split('.');
            var s = parts[0];
            var out = '';
            var th = this._lang() === 'en' ? ',' : '.';
            var dp = this._lang() === 'en' ? '.' : ',';
            while (s.length > 3) { out = th + s.slice(-3) + out; s = s.slice(0, -3); }
            out = s + out;
            if (parts.length > 1) { out = out + dp + parts[1]; }
            return (neg && Number(f) !== 0 ? '−' : '') + out;
        }

        // Whole euros: 1.234 € in es, EUR 1,234 in en.
        _fmtE(v) {
            var n = Number(v) || 0;
            var body = this._fmtNum(Math.abs(n), 0);
            var sign = (n < 0 && Math.abs(n) >= 0.5) ? '−' : '';
            if (this._lang() === 'en') { return sign + 'EUR ' + body; }
            return sign + body + ' €';
        }

        _fmtPct(v) {
            var x = this._fmtNum(Number(v) || 0, 1);
            return this._lang() === 'en' ? x + '%' : x + ' %';
        }

        _updateBriefing(state) {
            var cur = (state && state.currentPeriod) || 1;
            var maxP = (state && state.maxPeriods) || this.ROUNDS.length;
            var done = (state && state.history) ? state.history.length : 0;
            var finished = done >= maxP || cur > this.ROUNDS.length;
            var i, panel;
            for (i = 0; i < this.ROUNDS.length; i++) {
                panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!finished && (i + 1) === cur) ? 'block' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = finished ? 'none' : 'flex'; }
            var idx = Math.min(cur, this.ROUNDS.length) - 1;
            var nameEl = document.getElementById('roundName');
            if (nameEl) { nameEl.textContent = finished ? this._t('round_done') : this._t(this.ROUNDS[idx].nameKey); }
            var briefEl = document.getElementById('briefingText');
            if (briefEl) { briefEl.innerHTML = finished ? this._t('brief_done') : this._t(this.ROUNDS[idx].briefKey); }
            this._renderDynamic(state);
        }

        _renderDynamic(state) {
            var ds = (state && state.domainState) || {};
            var ps = ds.periods || [];
            var rounds = ds.rounds || [];
            var sEl = document.getElementById('semesterText');
            if (sEl) { sEl.innerHTML = ps.length ? this._periodHtml(ds, ps[ps.length - 1]) : this._t('sem_pending'); }
            var fbEl = document.getElementById('feedbackText');
            if (fbEl) {
                fbEl.classList.remove('ea2140-warn');
                var last = rounds.length ? rounds[rounds.length - 1] : null;
                if (!last) { fbEl.innerHTML = this._t('feedback_empty'); }
                else {
                    fbEl.innerHTML = this._feedbackHtml(ds, last);
                    if (last.verdictKey !== 'ok') { fbEl.classList.add('ea2140-warn'); }
                }
            }
        }

        _periodHtml(ds, q) {
            var v = {
                h: this._fmtNum(q.hours, 1), ot: this._fmtNum(q.ot, 1), sg: this._fmtNum(q.signed, 1), coll: this._fmtE(q.coll), res: this._fmtE(q.res), ok: this._fmtPct(q.okp)
            };
            var html = this._t('sem_body_' + q.t, v);
            html += '<span class="ea2140-cases">' + this._t('s_ops', {
                err: this._fmtNum(q.err, 1), late: this._fmtNum(q.late, 1), disc: this._fmtE(q.disc), nm: this._fmtNum(q.nmiss, 2), la: this._fmtNum(q.lost_alb, 1)
            }) + '</span>';
            html += '<span class="ea2140-cases">' + this._t('s_costs', {
                ch: this._fmtE(q.cost_h), fe: this._fmtE(q.fees), ce: this._fmtE(q.cost_err), cl: this._fmtE(q.cost_late + q.cost_not), lo: this._fmtE(q.cost_lost)
            }) + '</span>';
            html += '<span class="ea2140-cases">' + this._t('s_ar', { ar: this._fmtE(q.ar) }) + '</span>';
            if (q.disputes > 0) { html += '<span class="ea2140-cases">' + this._t('s_disp', { a: this._fmtNum(q.disputes, 1) }) + '</span>'; }
            if (q.lostcl > 0) { html += '<span class="ea2140-reveal">' + this._t('s_lostcl', { a: this._fmtNum(q.lostcl, 0) }) + '</span>'; }
            if (q.docs > 0) { html += '<span class="ea2140-reveal">' + this._t('s_docs', { a: this._fmtNum(q.docs, 0) }) + '</span>'; }
            if (q.pers > 0) { html += '<span class="ea2140-reveal">' + this._t('s_pers', { a: this._fmtNum(q.pers, 0) }) + '</span>'; }
            if (q.rights > 0) { html += '<span class="ea2140-reveal">' + this._t('s_rights', { a: this._fmtNum(q.rights, 0) }) + '</span>'; }
            var keys = ds.capKeys || [];
            var i;
            for (i = 0; i < keys.length; i++) {
                if (keys[i] === 'cap_keep') {
                    html += '<span class="ea2140-reveal">' + this._t('cap_keep', { a: this._fmtNum(ds.docsCum || 0, 0) }) + '</span>';
                } else {
                    html += '<span class="ea2140-reveal">' + this._t('cap_data', { a: this._fmtNum(ds.persCum || 0, 0), b: this._fmtNum(ds.rightsCum || 0, 0) }) + '</span>';
                }
            }
            return html;
        }

        _feedbackHtml(ds, r) {
            var v = { pts: this._fmtNum(Math.round(r.pts * 10) / 10, 1) };
            return '<strong>' + this._t('fb_points', v) + '</strong> ' + this._t('fb_r' + r.period + '_' + r.verdictKey, v);
        }

        _readSelect(id, allowed) {
            var el = document.getElementById(id);
            if (!el) { return null; }
            var val = String(el.value);
            if (allowed.indexOf(val) === -1) { return null; }
            return val;
        }

        validateDecisions(decisions) {
            var sim = window.mySimulation;
            var state = sim && sim.state ? sim.state : { currentPeriod: 1, history: [] };
            var period = state.currentPeriod || 1;
            var done = state.history ? state.history.length : 0;
            var warn = function(key) {
                sim.uiManager.showNotification(sim.t(key), 'warning');
                return false;
            };
            if (done >= this.ROUNDS.length || period > this.ROUNDS.length) { return warn('warn_finished'); }
            if (period === 1) {
                var inv = this._readSelect('r1_inv', CTRL.round1.inv);
                var mail = this._readSelect('r1_mail', CTRL.round1.mail);
                var nt = this._readSelect('r1_nt', CTRL.round1.nt);
                if (!inv || !mail || !nt) { return warn('warn_r1'); }
                decisions.round1 = { inv: inv, mail: mail, nt: nt };
                return true;
            }
            if (period === 2) {
                var appr = this._readSelect('r2_appr', CTRL.round2.appr);
                var sign = this._readSelect('r2_sign', CTRL.round2.sign);
                var arch = this._readSelect('r2_arch', CTRL.round2.arch);
                if (!appr || !sign || !arch) { return warn('warn_r2'); }
                decisions.round2 = { appr: appr, sign: sign, arch: arch };
                return true;
            }
            if (period === 3) {
                var first = this._readSelect('r3_first', CTRL.round3.first);
                var pay = this._readSelect('r3_pay', CTRL.round3.pay);
                var chg = this._readSelect('r3_chg', CTRL.round3.chg);
                if (!first || !pay || !chg) { return warn('warn_r3'); }
                decisions.round3 = { first: first, pay: pay, chg: chg };
                return true;
            }
            if (period === 4) {
                var req = this._readSelect('r4_req', CTRL.round4.req);
                var cv = this._readSelect('r4_cv', CTRL.round4.cv);
                var box = this._readSelect('r4_box', CTRL.round4.box);
                if (!req || !cv || !box) { return warn('warn_r4'); }
                decisions.round4 = { req: req, cv: cv, box: box };
                return true;
            }
            return warn('warn_finished');
        }

        calculateResults(state) {
            var out = this._computeRound(state);
            var self = this;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state); }, 400);
            return out;
        }

        // Round model. Every week is rebuilt from the decision history, so a resubmit is idempotent.
        _computeRound(state) {
            var ds = state.domainState;
            var raw = state.decisions || {};
            var period = state.currentPeriod || 1;
            var saved = ds.dec || {};
            var d = {};
            var k;
            for (k = 1; k <= period; k++) {
                if (raw['round' + k]) { d['round' + k] = raw['round' + k]; }
                else if (k < period && saved['round' + k]) { d['round' + k] = saved['round' + k]; }
            }
            ds.dec = JSON.parse(JSON.stringify(d));
            var rounds = [];
            var periods = [];
            var total = 0.0;
            var docs = 0.0, pers = 0.0, rights = 0.0;
            var cap = 100.0;
            var r, known, q, rub, orr, oq, outp, pts;
            for (r = 1; r <= period; r++) {
                known = knownUpTo(d, r);
                q = periodResult(known, r);
                docs += q.docs;
                pers += q.pers;
                rights += q.rights;
                rub = this._rubric(known, r);
                orr = C.W_RS * clamp((q.res - C.RS_LO[r - 1]) / (C.RS_HI[r - 1] - C.RS_LO[r - 1]), 0.0, 1.0);
                oq = C.W_OK * clamp((q.okp - C.OK_LO) / (C.OK_HI - C.OK_LO), 0.0, 1.0);
                outp = orr + oq;
                pts = rub + outp;
                total += pts;
                cap = capOf(docs, pers, rights);
                periods.push(q);
                rounds.push({ period: r, rub: rub, orr: orr, oq: oq, outp: outp, pts: pts, verdictKey: this._verdict(known, r) });
            }
            ds.rounds = rounds;
            ds.periods = periods;
            ds.docsCum = docs;
            ds.persCum = pers;
            ds.rightsCum = rights;
            ds.total = total;
            ds.cap = cap;
            var score = this._composite(ds);
            ds.capKeys = [];
            if (docs > 0 && total > Math.max(C.CAP_FLOOR, C.CAP_BASE - C.CAPK_W * docs)) { ds.capKeys.push('cap_keep'); }
            if ((pers > 0 || rights > 0) && total > Math.max(C.CAP_FLOOR, C.CAP_BASE - C.CAPD_W * pers - C.CAPR_W * rights)) { ds.capKeys.push('cap_data'); }
            ds.performance = { overallScore: score };
            ds.performanceTier = this._tier(score);
            ds.scoreHistory = (ds.scoreHistory || []).slice(0, period - 1);
            ds.scoreHistory[period - 1] = score;
            ds.scoreHistory.length = period;
            var last = periods[periods.length - 1];
            return {
                period: period,
                roundPoints: Math.round(rounds[period - 1].pts * 10) / 10,
                hours: Math.round(last.hours * 10) / 10,
                signed: Math.round(last.signed * 10) / 10,
                coll: Math.round(last.coll),
                res: Math.round(last.res),
                ok: Math.round(last.okp * 10) / 10,
                score: score,
                overallScore: score
            };
        }

        _rubric(dec, r) {
            var P = C.PTS;
            var d = dec['round' + r];
            var keys = Object.keys(CTRL['round' + r]);
            var s = 0, i;
            for (i = 0; i < keys.length; i++) { s += P[PTK[keys[i]] + r][d[keys[i]]]; }
            return s;
        }

        _verdict(dec, r) {
            var d = dec['round' + r];
            var order = VORDER[r];
            var i;
            for (i = 0; i < order.length; i++) {
                if (d[order[i][0]] === order[i][1]) { return order[i][1]; }
            }
            return 'ok';
        }

        _composite(ds) {
            var total = Math.min((ds && typeof ds.cap === 'number') ? ds.cap : 100, (ds && ds.total) || 0);
            return Math.max(0, Math.min(100, Math.round(total)));
        }

        _tier(score) {
            if (score >= 75) { return 'excellent'; }
            if (score >= 55) { return 'good'; }
            return 'beginner';
        }

        setupUI(uiManager) {
            var self = this;
            var lastP = function(ds) { var ps = (ds && ds.periods) || []; return ps.length ? ps[ps.length - 1] : null; };
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.performance.overallScore', function(v) { return (typeof v === 'number') ? String(v) : '0'; });
            uiManager.bind('hDisplay', 'domainState', function(ds) { var q = lastP(ds); return q ? self._fmtNum(q.hours, 1) : '—'; });
            uiManager.bind('signDisplay', 'domainState', function(ds) { var q = lastP(ds); return q ? self._fmtNum(q.signed, 1) : '—'; });
            uiManager.bind('collDisplay', 'domainState', function(ds) { var q = lastP(ds); return q ? self._fmtE(q.coll) : '—'; });
            uiManager.bind('resDisplay', 'domainState', function(ds) { var q = lastP(ds); return q ? self._fmtE(q.res) : '—'; });
            uiManager.bind('okDisplay', 'domainState', function(ds) { var q = lastP(ds); return q ? self._fmtPct(q.okp) : '—'; });
            uiManager.bind('sumDisplay', 'domainState', function(ds) {
                var ps = (ds && ds.periods) || [];
                if (!ps.length) { return '—'; }
                var s = 0.0, i;
                for (i = 0; i < ps.length; i++) { s += ps[i].res; }
                return self._fmtE(s);
            });
        }

        getChartConfig() {
            var t = this._t.bind(this);
            var sp = t('s_shortp');
            return {
                resChart: {
                    type: 'bar',
                    data: {
                        labels: [sp + '1', sp + '2', sp + '3', sp + '4'],
                        datasets: [{ label: t('chart_dataset'), data: [0, 0, 0, 0], backgroundColor: ['#2d4a6b', '#2d4a6b', '#2d4a6b', '#7a4a12'], borderWidth: 0 }]
                    },
                    options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { y: { ticks: { color: '#2b3440' } }, x: { ticks: { color: '#2b3440' } } } }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var ps = ds.periods || [];
            var hist = ds.scoreHistory || [];
            var data = [0, 0, 0, 0];
            var sp = this._t('s_shortp');
            var i;
            for (i = 0; i < ps.length && i < 4; i++) { data[i] = Math.round(ps[i].res); }
            return {
                resChart: {
                    labels: [sp + '1', sp + '2', sp + '3', sp + '4'],
                    datasets: [{ data: data, label: this._t('chart_dataset') + (hist.length ? ' · ' + sp + hist.length : '') }]
                }
            };
        }

        getHistoryTableConfig() {
            var self = this;
            return [
                { key: 'results.roundPoints', label: 'Points', i18nKey: 'col_points' },
                { key: 'results.hours', label: 'Hours', i18nKey: 'col_hours', formatter: function(v) { return self._fmtNum(v, 1); } },
                { key: 'results.signed', label: 'Signed', i18nKey: 'col_signed', formatter: function(v) { return self._fmtNum(v, 1); } },
                { key: 'results.coll', label: 'Collected', i18nKey: 'col_coll', formatter: function(v) { return self._fmtE(v); } },
                { key: 'results.res', label: 'Result', i18nKey: 'col_res', formatter: function(v) { return self._fmtE(v); } },
                { key: 'results.ok', label: 'On time', i18nKey: 'col_ok', formatter: function(v) { return self._fmtPct(v); } },
                { key: 'results.score', label: 'Score', i18nKey: 'col_score' }
            ];
        }

        getHint(state, results) {
            var ds = state.domainState || {};
            var r = (ds.rounds || [])[(results.period || 1) - 1];
            if (!r) { return null; }
            return this._t('hint_r' + r.period + '_' + r.verdictKey);
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) { return {}; }
            var ds = window.mySimulation.state.domainState;
            var ps = ds.periods || [];
            var score = this._composite(ds);
            var performance = 'Beginner';
            if (score >= 55) { performance = 'Good'; }
            if (score >= 75) { performance = 'Excellent'; }
            var res = 0.0, h = 0.0, sg = 0.0, ot = 0.0, okw = 0.0;
            var i;
            for (i = 0; i < ps.length; i++) { res += ps[i].res; h += ps[i].hours; sg += ps[i].signed; ot += ps[i].ot; okw += ps[i].okp; }
            var okp = ps.length ? okw / ps.length : 0.0;
            var insights = [];
            insights.push(res >= C.SUM_OK ? this._t('insight_res_ok') : (res >= 0 ? this._t('insight_res_mid') : this._t('insight_res_bad')));
            insights.push(okp >= C.OK_AVG ? this._t('insight_ok_ok') : this._t('insight_ok_bad'));
            insights.push(ps.length && ps[ps.length - 1].ot > 0 ? this._t('insight_h_bad') : this._t('insight_h_ok'));
            insights.push((ds.docsCum || 0) > 0 ? this._t('insight_keep_bad') : this._t('insight_keep_ok'));
            insights.push(((ds.persCum || 0) + (ds.rightsCum || 0)) > 0 ? this._t('insight_data_bad') : this._t('insight_data_ok'));
            insights.push(this._t('insight_next'));
            return {
                composite: score,
                overallScore: score,
                totalScore: score,
                score: score,
                res: res,
                hours: h,
                signed: sg,
                overtime: ot,
                okp: okp,
                docs: ds.docsCum || 0,
                pers: ds.persCum || 0,
                rights: ds.rightsCum || 0,
                rounds: (ds.scoreHistory || []).length,
                performance: performance,
                performanceKey: performance.toLowerCase(),
                performanceLabel: this._cl('grade_' + performance.toLowerCase(), performance),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var items = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '<div class="ea2140-cm">'
                + '<div class="ea2140-cm-score">' + score + '<span class="ea2140-cm-max">/100</span></div>'
                + '<div class="ea2140-cm-verdict">' + (s.performanceLabel || s.performance || '') + '</div>'
                + '<div class="ea2140-cm-kpis">'
                + '<div class="ea2140-cm-kpi">' + this._t('cm_kpi_res') + '<strong>' + this._fmtE(s.res) + '</strong></div>'
                + '<div class="ea2140-cm-kpi">' + this._t('cm_kpi_h') + '<strong>' + this._fmtNum(s.hours, 0) + '</strong></div>'
                + '<div class="ea2140-cm-kpi">' + this._t('cm_kpi_sign') + '<strong>' + this._fmtNum(s.signed, 0) + '</strong></div>'
                + '<div class="ea2140-cm-kpi">' + this._t('cm_kpi_ok') + '<strong>' + this._fmtPct(s.okp) + '</strong></div>'
                + '</div>'
                + '<div class="ea2140-cm-debrief">' + this._t('cm_debrief') + '</div>'
                + '<ul class="ea2140-cm-insights">' + items + '</ul>'
                + '</div>';
        }

